  "admin_html_00001" => '静态页面是把动态数据按要求生成静态页面，打开网页时不用去读取数据库。 区别：
1、动态站点网页打开相对静态页面要慢很多；
2、静态页面更容易搜索引挚的抓取，权重也比动态页面高。
3、动态页面容易有sql注入危险，静态页面不存在',
);
